// Turn n8n's error data into a short Telegram alert.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $json;

// Two shapes: a failed execution, or a trigger that failed before any execution started.
const workflow = e.workflow?.name ?? 'Unknown workflow';
const exec = e.execution ?? {};
const trigger = e.trigger ?? {};

const node = exec.lastNodeExecuted ?? trigger.error?.node?.name ?? 'unknown step';
const raw = exec.error?.message ?? trigger.error?.message ?? 'No error message';
const message = raw.length > 600 ? raw.slice(0, 600) + '...' : raw;
const mode = exec.mode ?? trigger.mode ?? '';
const when = $now.setZone('Asia/Dubai').toFormat('dd LLL, HH:mm');

let text = `🛠 <b>Workflow failed: ${esc(workflow)}</b>\n<i>${when} (Dubai)${mode ? ' · ' + esc(mode) : ''}</i>\n\n`;
text += `<b>Step:</b> ${esc(node)}\n<b>Error:</b> ${esc(message)}`;
if (exec.url) text += `\n\n<a href="${esc(exec.url)}">Open the execution</a>`;

return [{ json: { text } }];
